<?php
if(PHP_SAPI!=='cli'){http_response_code(403);exit(1);}$base=dirname(__DIR__);require $base.'/app/Config/App.php';require $base.'/app/Support/helpers.php';App\Config\App::loadEnv($base);$opt=getopt('',['database:']);$dbName=$opt['database']??app_env('DB_DATABASE','');if(!preg_match('/^[A-Za-z0-9_-]+$/',(string)$dbName)){fwrite(STDERR,"Banco invalido.\n");exit(2);}
try{$pdo=new PDO('mysql:host='.app_env('DB_HOST').';port='.app_env('DB_PORT').';dbname='.$dbName.';charset=utf8mb4',app_env('DB_USERNAME'),app_env('DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(Throwable $e){fwrite(STDERR,"AUSENTE: nao foi possivel consultar o schema.\n");exit(2);}$manifest=require $base.'/app/Config/required_schema.php';$missing=[];$divergent=[];
foreach($manifest as$table=>$spec){$s=$pdo->prepare('SELECT COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=:db AND TABLE_NAME=:t');$s->execute([':db'=>$dbName,':t'=>$table]);$found=[];foreach($s as$c)$found[$c['COLUMN_NAME']]=$c;if($found===[]){$missing[]='tabela '.$table;continue;}foreach($spec['columns']as$name=>$expected){if(!isset($found[$name])){$missing[]='coluna '.$table.'.'.$name;continue;}$actual=$found[$name];if(strtolower($actual['COLUMN_TYPE'])!==$expected['type']||$actual['IS_NULLABLE']!==$expected['nullable']||(string)$actual['COLUMN_DEFAULT']!==(string)$expected['default'])$divergent[]='coluna '.$table.'.'.$name;}$s=$pdo->prepare('SELECT DISTINCT INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=:db AND TABLE_NAME=:t');$s->execute([':db'=>$dbName,':t'=>$table]);$idx=$s->fetchAll(PDO::FETCH_COLUMN);foreach($spec['indexes']as$i)if(!in_array($i,$idx,true))$missing[]='indice '.$table.'.'.$i;$s=$pdo->prepare('SELECT CONSTRAINT_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=:db AND TABLE_NAME=:t AND REFERENCED_TABLE_NAME IS NOT NULL');$s->execute([':db'=>$dbName,':t'=>$table]);$fk=[];foreach($s as$f)$fk[$f['CONSTRAINT_NAME']]=[$f['COLUMN_NAME'],$f['REFERENCED_TABLE_NAME'],$f['REFERENCED_COLUMN_NAME']];foreach($spec['foreign_keys']as$n=>$expected)if(!isset($fk[$n]))$missing[]='foreign key '.$table.'.'.$n;elseif($fk[$n]!==$expected)$divergent[]='foreign key '.$table.'.'.$n;}
foreach($missing as$i)echo'AUSENTE: '.$i.PHP_EOL;foreach($divergent as$i)echo'DIVERGENTE: '.$i.PHP_EOL;if($missing||$divergent)exit(1);echo'OK: 31 tabelas, colunas, tipos, nullability, defaults, indices e foreign keys conferidos; somente leitura.'.PHP_EOL;
